import{_ as a,C as d,o,c as n,E as i,a2 as r}from"./chunks/framework.Cm6XCzck.js";const C=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.6","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.6","type":"implementation-case","domain":"TMPA","version":"I0.6","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.6.md","filePath":"zh/publications/implementation-case-i0.6.md","lastUpdated":1786085052000}'),l={name:"zh/publications/implementation-case-i0.6.md"};function s(c,t,p,h,P,g){const e=d("ArticleCover");return o(),n("div",null,[i(e,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"面向 S0.5 Reference Reader、FCoP、CodeFlowMu 与 WP-13 的作者本地工程证据基线。",version:"I0.6",status:"S0.5 工程证据草稿",languageHref:"/en/publications/implementation-case-i0.6",languageLabel:"English"}),t[0]||(t[0]=r(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="s0-5-reference-reader、fcop-v3-2-5、codeflowmu-本地快照与-wp-13" tabindex="-1">S0.5 Reference Reader、FCoP v3.2.5、CodeFlowMu 本地快照与 WP-13 <a class="header-anchor" href="#s0-5-reference-reader、fcop-v3-2-5、codeflowmu-本地快照与-wp-13" aria-label="Permalink to &quot;S0.5 Reference Reader、FCoP v3.2.5、CodeFlowMu 本地快照与 WP-13&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> Draft I0.6<br><strong>状态：</strong> 作者生成的实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>历史基线：</strong> I0.5 保留 S0.4 语料库与 WP-13 出版包<br><strong>证据采集：</strong> 2026-08-07，Asia/Shanghai<br><strong>证据包：</strong> <code>tmpa-i0.6-local-evidence-20260806-v2</code><br><strong>权威边界：</strong> 本报告仅提供工程证据，不具有规范性；TMPA 要求只由 Core Specification 定义。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I0.6 是首次使用新鲜产品证据对 TMPA Core S0.5 进行评估的 Implementation Case 修订。它严格分开四条轨道：S0.5 Reference Reader、FCoP v3.2.5 协议参考实现、从本地 CodeFlowMu 工作树逐字节隔离的运行快照，以及已经发布的 WP-13 多 Agent 证据门控案例。小典 AI 仍是工程谱系与候选现场案例；本轮没有可锁定的小典 S0.5 包，因此未运行。</p><p>S0.5 Reference Reader 在作者生成的合成 Fixture 上 <strong>14/14 PASS</strong>，但产品证据不继承这些结果。产品矩阵为 <strong>1 PASS、8 PARTIAL、3 NOT RUN、2 FAIL</strong>：C14 PASS；C02、C07 FAIL；C01、C03–C06、C09、C10、C13 PARTIAL；C08、C11、C12 NOT RUN。FCoP 记录 1,222 项通过、3 项失败、2 项跳过；CodeFlowMu 记录 Protocol Fixture 8/8、Runtime 1,420 通过 / 1 失败 / 1 跳过、Shell 770/770，Protocol、Runtime、Shell Typecheck 均通过。</p><p>因此，本报告支持“已实现”和“作者运行并演示”的工程结论，不支持完整 S0.5 一致性、独立验证或独立采用。失败项作为证据保留。WP-13 演示的是对未经验证完成声明的治理遏制，不证明模型已经停止产生幻觉。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>本报告回答四个问题：</p><ol><li>已发布的 Reference Reader 能否确定性执行 S0.5 规范解释？</li><li>FCoP 与 CodeFlowMu 当前有哪些 S0.5 产品级证据？</li><li>产品行为在哪些位置仍与 Core 契约不闭合？</li><li>WP-13 对不确定工具结果下的多 Agent 证据门控演示了什么？</li></ol><p>判断单元是“绑定到某项标准的证据声明”，不是对产品的总体声誉判断。四级证据必须分开：</p><table tabindex="0"><thead><tr><th>层级</th><th>I0.6 中的含义</th></tr></thead><tbody><tr><td>Specified</td><td>由 TMPA Core S0.5 定义</td></tr><tr><td>Implemented</td><td>代码或协议工件中存在对应机制</td></tr><tr><td>Demonstrated</td><td>作者运行产生可检查证据</td></tr><tr><td>Independently Adopted</td><td>独立组织采用并验证该机制</td></tr></tbody></table><p>I0.6 没有任何声明达到 Independently Adopted。</p><h1 id="_2-架构与组件边界" tabindex="-1">2. 架构与组件边界 <a class="header-anchor" href="#_2-架构与组件边界" aria-label="Permalink to &quot;2. 架构与组件边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture</span></span>
<span class="line"><span>       ↓ 规范契约</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>       ↓ 可复用协议 Profile</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>       ↓ 参考实现</span></span>
<span class="line"><span>fcop / fcop-mcp</span></span>
<span class="line"><span>       ↓ 下游采用</span></span>
<span class="line"><span>CodeFlowMu 应用与 WP-13 工作流</span></span></code></pre></div><p>TMPA 是治理架构。FCoP 是可复用协议 Profile，不是应用程序，也不能用“<code>pip install</code> 了一个产品”来定义协议。<code>fcop</code> 与 <code>fcop-mcp</code> Package 是协议参考实现。CodeFlowMu 是下游应用，使用 FCoP 概念和操作实现持久角色、任务、报告、复核、恢复与审计表面。WP-13 是一个有界 CodeFlowMu 现场案例。小典 AI 属于工程谱系，但本轮未作为 S0.5 产品输入执行。</p><p>概念分层与历史谱系必须分开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>概念分层：TMPA → FCoP → CodeFlowMu / 其他应用</span></span>
<span class="line"><span>历史谱系：小典实践 → 早期 TMPA → FCoP 提炼</span></span>
<span class="line"><span>                               → CodeFlowMu → 当前 TMPA 形式化</span></span></code></pre></div><h1 id="_3-证据设计与固定来源" tabindex="-1">3. 证据设计与固定来源 <a class="header-anchor" href="#_3-证据设计与固定来源" aria-label="Permalink to &quot;3. 证据设计与固定来源&quot;">​</a></h1><p>V2 包保留命令、环境、stdout/stderr、结构化摘要、标准矩阵、来源清单、隐私脱敏报告与 SHA-256 Manifest。V2 只修正 V1 的叙述错误，没有重跑测试，也没有改变任何原始产品日志。</p><table tabindex="0"><thead><tr><th>来源</th><th>固定身份</th><th>证据作用</th><th>边界</th></tr></thead><tbody><tr><td>TMPA Publication</td><td>Commit <code>653e7ba0…</code></td><td>S0.5 Schema、Fixture、Reference Reader</td><td>作者实现</td></tr><tr><td>FCoP</td><td>Tag <code>v3.2.5</code>，Commit <code>b3dc2343…</code></td><td>协议与干净 detached 参考实现</td><td>公开固定源码</td></tr><tr><td>CodeFlowMu</td><td>Base <code>c4ebc146…</code>，<code>0.3.0-alpha</code></td><td>隔离产品/测试快照</td><td>脏本地源码：39 Modified、47 Untracked</td></tr><tr><td>WP-13</td><td>Commit <code>609571dd…</code>，V3 ZIP SHA-256 <code>5b5eda30…</code></td><td>多 Agent 事实复核案例</td><td>作者生成、角色分离 QA；非第三方验证</td></tr><tr><td>小典 AI</td><td>无固定 S0.5 包</td><td>谱系与候选案例</td><td>NOT RUN</td></tr></tbody></table><p>CodeFlowMu 运行时使用与工作树逐字节一致的隔离快照，但它不是稳定公开 Release，只能支持作者本地工程证据。</p><h1 id="_4-fcop-与-codeflowmu-工程映射" tabindex="-1">4. FCoP 与 CodeFlowMu 工程映射 <a class="header-anchor" href="#_4-fcop-与-codeflowmu-工程映射" aria-label="Permalink to &quot;4. FCoP 与 CodeFlowMu 工程映射&quot;">​</a></h1><p>FCoP 通过带路由的文本对象、生命周期路径、原子发布、追加式迁移、明确角色、独立 REPORT/REVIEW、ISSUE、ALERT 与 History 提供项目可见协作。它使协调事实在短暂 Agent Session 之外仍可检查和重建。</p><p>CodeFlowMu 在协议之上增加应用运行行为：持久工作身份、PM/DEV/QA/OPS 角色界面、Skill 与工具调用、Workflow 调度、Review Gate、依赖等待、恢复、审批边界及用户界面。这些机制可以实现或演示部分 S0.5，但不能重定义 FCoP 协议或 TMPA Core 标准。</p><p>共同的主要缺口是受维护的产品投影：把原生工件转换成完整 S0.5 Governance Object 与 Reader Result 表面。在该投影完成前，局部门禁可以工作，但规范对象、Issue Code、三值判断与确定性聚合视图仍可能不完整。</p><h1 id="_5-已执行测试基线" tabindex="-1">5. 已执行测试基线 <a class="header-anchor" href="#_5-已执行测试基线" aria-label="Permalink to &quot;5. 已执行测试基线&quot;">​</a></h1><p>所有主运行均由作者执行。Reference Reader PASS 不得复制为 Product PASS。</p><table tabindex="0"><thead><tr><th>轨道</th><th style="text-align:right;">结果</th><th style="text-align:right;">Exit</th><th>解释</th></tr></thead><tbody><tr><td>S0.5 Reference Reader</td><td style="text-align:right;">14 PASS</td><td style="text-align:right;">0</td><td>合成 Fixture 上的可执行规范解释</td></tr><tr><td>FCoP v3.2.5 全量</td><td style="text-align:right;">1,222 PASS、3 FAIL、2 SKIP</td><td style="text-align:right;">1</td><td>保留三项产品断言失败</td></tr><tr><td>FCoP Library CI 子集</td><td style="text-align:right;">907 PASS、1 FAIL</td><td style="text-align:right;">1</td><td><code>parent</code> 持久化/读回缺口</td></tr><tr><td>FCoP MCP CI 子集</td><td style="text-align:right;">78 PASS、2 FAIL</td><td style="text-align:right;">1</td><td>Report Lifecycle 与 Tool Surface Snapshot 缺口</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">8/8</td><td style="text-align:right;">0</td><td>5 个合法与 3 个预期非法 Fixture</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,420 PASS、1 FAIL、1 SKIP</td><td style="text-align:right;">1</td><td>一项人工提示语契约不匹配</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">770/770</td><td style="text-align:right;">0</td><td>完整隔离 Shell Snapshot</td></tr><tr><td>三包 Typecheck</td><td style="text-align:right;">全部通过</td><td style="text-align:right;">0</td><td>仅静态检查</td></tr><tr><td>WP-13 V3 验证</td><td style="text-align:right;">PASS</td><td style="text-align:right;">0</td><td>23/23 内部 Hash 与结构化数据检查</td></tr></tbody></table><p>两份 FCoP stdout 被规范化为可解码 UTF-8，并含 U+FFFD 替换字符。计数、退出码与已识别失败项未受影响，但证据包不声明原始进程输出得到逐字节无损保存。</p><h1 id="_6-c01–c14-产品结果" tabindex="-1">6. C01–C14 产品结果 <a class="header-anchor" href="#_6-c01–c14-产品结果" aria-label="Permalink to &quot;6. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 标准</th><th style="text-align:right;">Reader</th><th style="text-align:right;">Product</th><th>产品证据边界</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>已运行选定正负 Schema 路径；未覆盖完整规范对象表面。</td></tr><tr><td>C02</td><td>主载体与不可变性</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>FAIL</strong></td><td>FCoP 写入表面接受 <code>parent</code>，但持久化/读回及发布 Surface Snapshot 未闭合。</td></tr><tr><td>C03</td><td>重复身份</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>存在重复/冲突机制；规范产品隔离输出不完整。</td></tr><tr><td>C04</td><td>串行流连续性与异步推进</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>排序与依赖机制已运行；未形成完整规范偏序图。</td></tr><tr><td>C05</td><td>角色权限</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>角色门禁已运行；完整 S0.5 权限 Issue/Judgment 未输出。</td></tr><tr><td>C06</td><td>生命周期合法性</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>生命周期控制已运行；必需的完整三值规范输出未形成。</td></tr><tr><td>C07</td><td>职责分离与人工控制</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>FAIL</strong></td><td>人工控制结构存在，但一项强制提示语契约断言失败。</td></tr><tr><td>C08</td><td>完整性篡改</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>相邻 Hash 证据不能替代产品标准运行。</td></tr><tr><td>C09</td><td>缺失引用</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>失败可见；规范 <code>undetermined</code> 传播不完整。</td></tr><tr><td>C10</td><td>禁止环</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>本地 Cycle Detection 通过；规范受影响子图隔离未运行。</td></tr><tr><td>C11</td><td>确定性重建</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>只有 Reference Reader 完成所需排列等价重建。</td></tr><tr><td>C12</td><td>冲突保留</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>存在相邻冲突机制；精确产品标准未运行。</td></tr><tr><td>C13</td><td>恢复</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>已演示文件事实恢复；完整全新 Reader 重建未完成。</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>PASS</strong></td><td>产品测试支持终态历史与权限行为保留。</td></tr></tbody></table><p>产品聚合：<strong>1 PASS / 8 PARTIAL / 3 NOT RUN / 2 FAIL</strong>，不构成一致性通过。</p><h1 id="_7-保留失败分析" tabindex="-1">7. 保留失败分析 <a class="header-anchor" href="#_7-保留失败分析" aria-label="Permalink to &quot;7. 保留失败分析&quot;">​</a></h1><h2 id="_7-1-c02-fcop-parent-闭合" tabindex="-1">7.1 C02：FCoP <code>parent</code> 闭合 <a class="header-anchor" href="#_7-1-c02-fcop-parent-闭合" aria-label="Permalink to &quot;7.1 C02：FCoP \`parent\` 闭合&quot;">​</a></h2><p>FCoP 的三项失败不等于 FCoP 协议定义失败。它们暴露参考实现的 Release 一致性缺口：可选 <code>parent</code> 已出现在当前 API/MCP 表面，但完整写入—持久化—读回路径与保存的 Public Surface Snapshot 尚未全部同步。在同一对象完成完整 Round-trip、Surface Snapshot 通过受控发布更新并重跑全量测试前，C02 保持 FAIL。</p><h2 id="_7-2-c07-人工裁决提示语契约" tabindex="-1">7.2 C07：人工裁决提示语契约 <a class="header-anchor" href="#_7-2-c07-人工裁决提示语契约" aria-label="Permalink to &quot;7.2 C07：人工裁决提示语契约&quot;">​</a></h2><p>CodeFlowMu Runtime 测试期望 <code>需 ADMIN 人工裁定</code> 或 <code>需人工裁定</code>，实际可读输出为 <code>需 ADMIN/PM 人工裁定</code>。结构化字段仍正确：<code>decision=needs_human</code>、<code>fact_check_verdict=needs_admin</code>、<code>awaiting_pm_decision=true</code>，Lifecycle 没有推进。</p><p>因此，失败原因是提示语契约不一致，不是中文编码损坏。原始强制断言确实失败，C07 必须保持 FAIL，直至产品和测试维护者裁定 <code>ADMIN/PM</code> 是预期产品变更还是测试期望过时，完成相应产品或测试修改，并重跑完整 Runtime Acceptance Suite。</p><h1 id="_8-wp-13-多-agent-证据门控案例" tabindex="-1">8. WP-13 多 Agent 证据门控案例 <a class="header-anchor" href="#_8-wp-13-多-agent-证据门控案例" aria-label="Permalink to &quot;8. WP-13 多 Agent 证据门控案例&quot;">​</a></h1><p>WP-13 研究多 Agent 治理链能否阻止未经验证的完成声明成为权威交付事实。DEV 子执行结束时出现带完成意味的语言，但退出状态、测试、Commit 与正式 REPORT 尚未全部确认。PM 检查持久事实，不放行，也不派 QA。工具恢复后，DEV 在原任务补齐实现、Commit <code>609571dd…</code> 与正式报告；角色分离 QA 重跑 27 项测试、Typecheck 与 Diff Check 并通过。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>带完成意味的声明</span></span>
<span class="line"><span>      ↓ 持久证据不完整</span></span>
<span class="line"><span>PM 事实复核 → 保持等待 / 不放行 / 不派 QA</span></span>
<span class="line"><span>      ↓ 原任务恢复</span></span>
<span class="line"><span>DEV Commit + REPORT</span></span>
<span class="line"><span>      ↓ 独立角色</span></span>
<span class="line"><span>QA 重跑 + REPORT</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>进入授权裁决的候选证据</span></span></code></pre></div><p>在第一个观察时刻，“WP-13 已完成”既未被证据建立为 <code>valid</code>，也没有被证明为 <code>invalid</code>；适当的 S0.5 分析判断是 <code>undetermined</code>。这是 TMPA 后验投影，不是原生应用当时已经输出完整 S0.5 Reader Envelope。</p><p>该案例演示治理遏制、角色分离、原任务恢复与证据补齐；它不证明消除幻觉、第三方独立验证、原快照内已经终态批准、密码学来源或独立采用。</p><p>V3 包记录 <code>runtime_bound: false</code>，快照结束时 TASK-019/020 仍为 <code>review / pending</code>。Gate C Accept 是之后的独立生命周期事实。<code>DEV complete</code>、<code>QA PASS</code>、<code>Gate C accept</code>、<code>done</code> 与 <code>archive</code> 不能合并成一个状态。</p><h1 id="_9-三值治理解释" tabindex="-1">9. 三值治理解释 <a class="header-anchor" href="#_9-三值治理解释" aria-label="Permalink to &quot;9. 三值治理解释&quot;">​</a></h1><table tabindex="0"><thead><tr><th>判断</th><th>常见视图</th><th>含义</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>必需证据与适用规则建立结论。</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>确定性违规排除受影响证据或动作。</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>证据缺失、冲突或等待授权人工决定。</td></tr></tbody></table><p>FCoP 与 CodeFlowMu 已暴露该模型所需的许多来源事实，但 I0.6 不声明任一产品对全部标准都输出完整 S0.5 规范图、Issue Set、Judgment 与 View。Reference Reader PASS 建立可执行解释；产品裁决描述当前投影与执行缺口。</p><h1 id="_10-可复现性与证据质量" tabindex="-1">10. 可复现性与证据质量 <a class="header-anchor" href="#_10-可复现性与证据质量" aria-label="Permalink to &quot;10. 可复现性与证据质量&quot;">​</a></h1><p>V2 ZIP 含 125 个条目和 122 个 Payload Hash。Archive CRC、SHA-256 Manifest、45 个 JSON、相关 JSONL、经过明确规范化后的严格 UTF-8 解码、文件名安全、绝对路径扫描与凭证扫描均通过。V1/V2 的全部原始日志逐字节一致；V2 只修订摘要、矩阵语言、验证元数据与编码边界。</p><p>最强可复核结论是：S0.5 Reference Reader 在固定合成 Fixture 上 14/14 PASS；FCoP 与 CodeFlowMu 的测试计数和失败均保留在原始日志；WP-13 V3 通过内部包验证；产品矩阵遵守“一项强制断言失败即不得 PASS”的严格规则。</p><p>该包是作者本地证据，没有签名、独立可信时间戳、第三方重跑，也不是稳定公开的 CodeFlowMu Release Snapshot。</p><h1 id="_11-局限" tabindex="-1">11. 局限 <a class="header-anchor" href="#_11-局限" aria-label="Permalink to &quot;11. 局限&quot;">​</a></h1><ol><li>FCoP、CodeFlowMu 与证据包由项目参与者维护，存在作者偏差。</li><li>CodeFlowMu 来源是脏的本地工作树，尽管运行使用隔离快照。</li><li>C08、C11、C12 缺少精确产品执行。</li><li>8 项 PARTIAL 缺少完整规范产品输出。</li><li>C02 与 C07 保留已执行失败。</li><li>小典 AI 没有固定 S0.5 包，本轮 NOT RUN。</li><li>尚未建立代表性 SME 性能、采用成本、比较基线、广泛故障恢复、拜占庭韧性或第三方采用。</li><li>两份规范化 FCoP 日志含 U+FFFD，限制字节级取证声明。</li></ol><h1 id="_12-工程路线" tabindex="-1">12. 工程路线 <a class="header-anchor" href="#_12-工程路线" aria-label="Permalink to &quot;12. 工程路线&quot;">​</a></h1><ol><li>闭合 FCoP <code>parent</code> 持久化/读回与 Release Surface Snapshot，并重跑全量套件。</li><li>裁定 CodeFlowMu <code>ADMIN/PM</code> 提示语契约，实施批准的产品或测试变更，再重跑完整 Runtime。</li><li>发布可取回的干净 CodeFlowMu Candidate 或复现快照。</li><li>实现受维护的 FCoP 与 CodeFlowMu S0.5 投影适配器。</li><li>执行 C08、C11、C12，并补齐全部 PARTIAL 的规范输出。</li><li>在新增小典 S0.5 声明前建立固定证据包。</li><li>获得独立重跑并保留全部差异。</li></ol><h1 id="_13-工程结论" tabindex="-1">13. 工程结论 <a class="header-anchor" href="#_13-工程结论" aria-label="Permalink to &quot;13. 工程结论&quot;">​</a></h1><p>I0.6 把 Implementation Case 从历史 S0.4 基线推进为新的 S0.5 作者运行证据基线。结果刻意保留混合状态：Reference Reader 通过全部 14 项合成标准，产品证据则为 1 PASS、8 PARTIAL、3 NOT RUN、2 FAIL。这比只展示成功更有信息量，因为它在不削弱规范契约的前提下定位了具体实现与投影缺口。</p><p>FCoP 仍是协议层，其 Package 是参考实现；CodeFlowMu 仍是下游应用。WP-13 提供一个有边界的多 Agent 治理案例，说明持久证据和角色分离能够遏制未经验证的完成声明。这些工程观察均不证明 TMPA 理论、完整产品一致性或独立采用。</p><h1 id="工件可用性" tabindex="-1">工件可用性 <a class="header-anchor" href="#工件可用性" aria-label="Permalink to &quot;工件可用性&quot;">​</a></h1><p>完整 V2 证据包：<a href="/joinwell52/evidence/tmpa/i0.6/tmpa-i0.6-local-evidence-20260806-v2.zip">tmpa-i0.6-local-evidence-20260806-v2.zip</a>，SHA-256：<code>c55cb41fb90f63216fafe6e5b552f4917e56910d120d3b51486f96eba066c2d0</code>。可直接审阅的 Matrix、Test Summary、Source Inventory、Package Validation 与 Redaction Metadata 位于 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.5/external-runs/20260806-local-evidence-v2" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.5/external-runs/20260806-local-evidence-v2</code></a>。</p><p>历史 S0.4 语料库仍位于 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>，WP-13 V3 仍位于本站 <code>/evidence/tmpa/i0.5/</code>。Git History 是出版版本历史，不存在具有编辑权威的第二套论文档案。</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.5.” GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.7.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” tag v3.2.5, commit <code>b3dc23439c6aaa6a6b3765655b87e5924e0257f9</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. Local isolated evidence snapshot based on commit <code>c4ebc146cb8ef0409a4c9eb571a8f2432ade3bd0</code>, version <code>0.3.0-alpha</code>, captured 2026-08-07.</p><p>[5] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” commit <code>609571ddb22d1fbb2bfb5e54692c07beeef4cf23</code>, 2026.</p><p>[6] TMPA Project. “I0.6 Local Engineering Evidence V2,” package <code>tmpa-i0.6-local-evidence-20260806-v2</code>, 2026.</p>`,69))])}const A=a(l,[["render",s]]);export{C as __pageData,A as default};
